Github actions hugo site .github/workflows/deploy.yml
name: Deploy site on: push jobs: deploy: runs-on: ubuntu-latest steps: - name: Git checkout uses: actions/checkout@v4 - name: Setup hugo uses: peaceiris/actions-hugo@v3 with: hugo-version: &#34;0.147.0&#34; - name: Build site run: hugo --minify - name: Deploy site uses: peaceiris/actions-gh-pages@v4 with: deploy_key: ${{ secrets.ACTIONS_DEPLOY_KEY }} external_repository: name/repo publish_dir: ./public cname: example.com В данном случае, собранный сайт загружается в другой репозиторий, для этого в репозитории с исходниками, в разделе Actions secrets and variables создаем Actions Key, а в целевом репозитории создаем Deploy keys с соответствующим именем.
ssh-keygen -t ed25519 -C &#34;github-actions-deploy&#34; -f github-actions-deploy -N &#34;&#34;
